const $=s=>document.querySelector(s);
const state={data:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=1)=>Number.isFinite(Number(n))?Number(n).toLocaleString('ko-KR',{maximumFractionDigits:d,minimumFractionDigits:d}):'-';
const pct=n=>Number.isFinite(Number(n))?`${Number(n)>=0?'+':''}${fmt(n)}%`:'-';
const naverStock=code=>`https://finance.naver.com/item/main.naver?code=${encodeURIComponent(code)}`;
const naverTheme=no=>`https://finance.naver.com/sise/sise_group_detail.naver?type=theme&no=${encodeURIComponent(no)}`;
function showApp(ok){$('#auth').classList.toggle('hidden',ok);$('#app').classList.toggle('hidden',!ok);}
async function checkSession(){try{const r=await fetch('/api/naver-theme-rotation/session',{cache:'no-store'}),j=await r.json();if(j.ok){showApp(true);await loadDaily();}else showApp(false);}catch{showApp(false);}}
$('#authForm').addEventListener('submit',async e=>{e.preventDefault();const msg=$('#authMsg');msg.textContent='인증 확인 중…';const r=await fetch('/api/naver-theme-rotation/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:$('#code').value})});const j=await r.json();if(!r.ok){msg.textContent=j.message||'인증 실패';return;}msg.textContent='인증 완료';showApp(true);await loadDaily();});

function setBusy(b,text='분석 중…'){const btn=$('#runBtn');btn.disabled=b;btn.textContent=b?text:'전체 테마 새로 분석';$('#progress').classList.toggle('hidden',!b);}
async function loadDaily(){setBusy(true,'오늘 자동 분석 불러오는 중…');try{const r=await fetch('/api/naver-theme-rotation/analyze',{cache:'no-store'});if(r.status===401){location.reload();return;}const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'분석 실패');applyData(j);}catch(e){$('#progress').classList.remove('hidden');$('#progress').textContent=`자동 분석을 불러오지 못했습니다. ‘전체 테마 새로 분석’을 눌러 다시 시도하세요. ${e.message||''}`;}finally{setBusy(false);}}
async function runFresh(){setBusy(true);$('#progress').textContent='네이버 전체 테마 → 뉴스 재평가 → 상위 30 → 소외 5 → 20종목 순서로 계산 중입니다.';try{const r=await fetch('/api/naver-theme-rotation/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lookback:+$('#lookback').value})});if(r.status===401){location.reload();return;}const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'분석 실패');applyData(j);}catch(e){alert(`분석 중 오류가 발생했습니다.\n${e.message||e}`);}finally{setBusy(false);}}
$('#runBtn').addEventListener('click',runFresh);

function applyData(j){state.data=j;$('#asOf').textContent=new Date(j.asOf).toLocaleString('ko-KR');$('#themeCount').textContent=j.totalThemeCount;$('#flowAll').textContent=j.totalThemeCount;$('#newsCount').textContent=j.method?.newsEnriched??'-';$('#stockCount').textContent=j.final20?.length??0;$('#excelBtn').disabled=false;$('#progress').classList.add('hidden');render();}
function colorClass(v){return v>=80?'high':v>=65?'mid':'low';}
function renderSelected(){const rows=state.data?.selected5||[];$('#selectedThemes').innerHTML=rows.length?rows.map((t,i)=>`<article class="selected-theme"><div class="rank">소외 ${i+1}위 · 전망 ${t.rank||'-'}위</div><h3><a class="theme-link" href="${naverTheme(t.no)}" target="_blank" rel="noopener">${esc(t.name)}</a></h3><div class="metrics"><div><span>전망점수</span><b>${fmt(t.outlook)}</b></div><div><span>소외지수</span><b>${fmt(t.alienation)}</b></div><div><span>고점대비 낙폭</span><b>${fmt(t.drawdown)}%</b></div><div><span>뉴스점수</span><b>${fmt(t.newsScore)}</b></div></div></article>`).join(''):'<div class="empty-card">가격 이력을 확보한 소외 테마가 없습니다.</div>';}
function renderStocks(){const rows=state.data?.final20||[];$('#stockRows').innerHTML=rows.length?rows.map(s=>`<tr><td><b>${s.rank}</b></td><td>${esc(s.themeName)}</td><td><a class="stock-link" href="${naverStock(s.code)}" target="_blank" rel="noopener"><b>${esc(s.name)}</b></a><div class="stock-reason" title="${esc(s.reason)}">${esc((s.reason||'').slice(0,95))}${(s.reason||'').length>95?'…':''}</div></td><td><span class="badge ${s.tier==='핵심'?'good':s.tier==='도전자'?'watch':'risk'}">${esc(s.tier||'-')}</span></td><td class="score ${colorClass(s.qualityScore||0)}">${fmt(s.qualityScore)}</td><td>${fmt(s.current,0)}</td><td>${fmt(s.drawdown)}%</td><td class="score ${(s.momentum20||0)>=0?'high':'low'}">${pct(s.momentum20)}</td><td class="cap-proxy">${s.marketCap?fmt(s.marketCap,0):'-'}</td><td><a href="${naverStock(s.code)}" target="_blank" rel="noopener">보기</a></td></tr>`).join(''):'<tr><td colspan="10" class="empty">최종 종목이 없습니다.</td></tr>';}
function renderThemes(){if(!state.data)return;const mode=$('#viewMode').value,q=$('#search').value.trim().toLowerCase(),src=mode==='all'?state.data.allThemes:state.data.top30;$('#themeTableTitle').textContent=mode==='all'?'네이버 전체 테마 평가':'전망 상위 30개 테마';const selected=new Set((state.data.selected5||[]).map(x=>x.no));const rows=src.filter(t=>!q||String(t.name).toLowerCase().includes(q)||(t.leaders||[]).some(x=>String(x).toLowerCase().includes(q)));$('#themeRows').innerHTML=rows.length?rows.map(t=>`<tr><td><b>${t.rank}</b></td><td class="selected-mark">${selected.has(t.no)?'★':''}</td><td><a class="theme-link" href="${naverTheme(t.no)}" target="_blank" rel="noopener">${esc(t.name)}</a><div class="tier">${esc((t.leaders||[]).join(' · '))}</div></td><td class="score ${colorClass(t.outlook)}">${fmt(t.outlook)}</td><td class="score ${t.dayPct>=0?'high':'low'}">${pct(t.dayPct)}</td><td class="score ${t.threeDayPct>=0?'high':'low'}">${pct(t.threeDayPct)}</td><td>${fmt(t.newsScore)}</td><td>${fmt(t.alienation)}</td><td>${Number.isFinite(Number(t.drawdown))?fmt(t.drawdown)+'%':'-'}</td><td>${fmt(t.opportunity)}</td></tr>`).join(''):'<tr><td colspan="10" class="empty">검색 결과가 없습니다.</td></tr>';}
function render(){renderSelected();renderStocks();renderThemes();}
$('#viewMode').addEventListener('change',renderThemes);$('#search').addEventListener('input',renderThemes);$('#lookback').addEventListener('input',()=>$('#lookbackVal').textContent=$('#lookback').value+'일');

$('#excelBtn').addEventListener('click',()=>{if(!state.data||!window.XLSX)return;const d=state.data;
  const top30=(d.top30||[]).map(t=>({전망순위:t.rank,선택5테마:t.selected?'Y':'',테마:t.name,전망점수:+Number(t.outlook).toFixed(1),소외지수:Number.isFinite(Number(t.alienation))?+Number(t.alienation).toFixed(1):'',고점대비낙폭:Number.isFinite(Number(t.drawdown))?+Number(t.drawdown).toFixed(1):'','1일등락률':t.dayPct,'3일평균':t.threeDayPct,뉴스점수:+Number(t.newsScore).toFixed(1),매수기회:Number.isFinite(Number(t.opportunity))?+Number(t.opportunity).toFixed(1):'',네이버테마:naverTheme(t.no)}));
  const selected=(d.selected5||[]).map((t,i)=>({소외순위:i+1,전망순위:t.rank,테마:t.name,전망점수:+Number(t.outlook).toFixed(1),소외지수:+Number(t.alienation).toFixed(1),고점대비낝폭:+Number(t.drawdown).toFixed(1),뉴스점수:+Number(t.newsScore).toFixed(1),네이버테마:naverTheme(t.no)}));
  const stocks=(d.final20||[]).map(s=>({순위:s.rank,테마:s.themeName,종목:s.name,코드:s.code,구분:s.tier,종합점수:+Number(s.qualityScore).toFixed(1),현재가:s.current??'',고점대비낙폭:s.drawdown==null?'':+Number(s.drawdown).toFixed(1),'20일등락률':s.momentum20==null?'':+Number(s.momentum20).toFixed(1),시총프록시:s.marketCap||'',테마편입사유:s.reason,네이버증권:naverStock(s.code)}));
  const all=(d.allThemes||[]).map(t=>({순위:t.rank,테마:t.name,전망점수:+Number(t.outlook).toFixed(1),구조성:t.structural,정책성:t.policy,글로벌:t.global,시장흐름:+Number(t.market).toFixed(1),내부확산:+Number(t.breadth).toFixed(1),'1일등락률':t.dayPct,'3일평균':t.threeDayPct,뉴스점수:+Number(t.newsScore).toFixed(1),네이버테마:naverTheme(t.no)}));
  const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(top30),'전망상위30');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(selected),'소외5테마');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(stocks),'최종20종목');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(all),'전체테마');XLSX.writeFile(wb,`Naver_Theme_Rotation_Radar_${new Date().toISOString().slice(0,10)}.xlsx`);
});
checkSession();
